export const uid=()=>crypto.randomUUID();
export function slots(r,old=[]){return Array.from({length:r.levels*r.cols},(_,i)=>{const level=Math.floor(i/r.cols)+1,col=i%r.cols+1;return old.find(s=>s.level===level&&s.col===col)||{id:uid(),level,col,code:`${r.name}-${String(col).padStart(2,'0')}-${level}`,cartons:0};});}
export function seed(){const racks=[];for(let i=0;i<18;i++){const fgCode=i%2?'FG02':'FG01',r={id:uid(),spaceId:'main',fgCode,name:`R-${String(i+1).padStart(2,'0')}`,x:3+(i%3)*10,y:4+Math.floor(i/3)*4,cols:6,levels:1+i%3,width:1.35,depth:1.4,levelHeight:1.5,rotation:0};r.slots=slots(r).map((s,j)=>({...s,cartons:(j+i)%5===0?0:3+(j*7+i*3)%18}));racks.push(r);}return {schemaVersion:2,racks};}
export const fgColor=code=>code==='FG01'?'#c9e4f5':code==='FG02'?'#f7d9bc':'#f9e6a8';
export function migrate(saved){if(!saved)return null;if(saved.schemaVersion===2)return saved;if(saved.schemaVersion!==1||!Array.isArray(saved.racks))return null;const result=structuredClone(saved);result.schemaVersion=2;result.racks.forEach(r=>{r.spaceId='main';r.fgCode=r.zone==='B'?'FG02':'FG01';delete r.zone;});return result;}
export function validate(r,racks){if(!r.name.trim())throw Error('请填写货架名称');for(const key of ['x','y','cols','levels','width','depth','levelHeight','rotation'])if(!Number.isFinite(r[key]))throw Error('请输入有效数值');if(r.cols<1||r.cols>20||!Number.isInteger(r.cols)||r.levels<1||r.levels>3||!Number.isInteger(r.levels))throw Error('列数为 1–20，层数为 1–3');if(r.width<.3||r.width>5||r.depth<.3||r.depth>5||r.levelHeight<.3||r.levelHeight>5)throw Error('尺寸需在 0.3–5 米之间');if(Math.abs(r.x)>200||Math.abs(r.y)>200)throw Error('坐标需在 -200 至 200 米之间');if(racks.some(x=>x.id!==r.id&&x.name===r.name))throw Error('货架名称不能重复');}
